<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {onShow,onLoad,onHide,onUnload} from '@dcloudio/uni-app'
import TeachingShell from '../teaching/shared/TeachingShell.vue'
import {currentSession,restoreSession} from '../../utils/session'
import {archiveService,archiveRequestId,type StudentArchiveDTO,type ArchiveAction,type ArchiveBooking} from '../../services/student-archive'
import type {ArchiveReview,ArchiveReport,ArchiveAnalysis} from '../../../shared/student-archive'
import {BusinessError,errorMessage} from '../../services/errors'
import {apiMode} from '../../config/runtime'
import {confirmAction,formatTime} from '../tutor/shared/page'
const role=computed(()=>currentSession.value?.user.role)
const allowed=computed(()=>role.value==='parent'||role.value==='tutor')
const list=ref<StudentArchiveDTO[]>([]),archive=ref<StudentArchiveDTO|null>(null),bookings=ref<ArchiveBooking[]>([])
const busy=ref(false),ready=ref(false),error=ref(''),feedback=ref(''),tab=ref('overview'),requestedBooking=ref(''),selectedBooking=ref('')
const nickname=ref(''),grade=ref(''),goals=ref(''),trial=ref(''),observation=ref(''),question=ref(''),answer=ref(''),reference=ref(''),submissionId=ref(''),consent=ref(false)
const reportText=ref(''),nextLesson=ref(''),reportReviewId=ref(''),reportId=ref(''),answers=ref<Record<string,string>>({}),grantLevel=ref<'summary'|'learning'>('summary'),grantDays=ref('30'),selectedReports=ref<string[]>([]),revokeBooking=ref('')
const editingReview=ref<{id:string;analysis:ArchiveAnalysis;teacherNote:string}|null>(null),observationId=ref(''),requestedSubmission=ref('')
let epoch=0
type PendingAction={id:string;revision:number;action:ArchiveAction;requestId:string;message:string;owner:typeof currentSession.value}
let pendingAction:PendingAction|null=null,creationKey:{fingerprint:string;requestId:string}|null=null
const canRetry=ref(false)
const identity=()=>currentSession.value
function clearInputs(){pendingAction=null;canRetry.value=false;creationKey=null;trial.value='';observation.value='';observationId.value='';editingReview.value=null;question.value='';answer.value='';reference.value='';submissionId.value='';consent.value=false;reportText.value='';nextLesson.value='';reportReviewId.value='';reportId.value='';answers.value={};selectedReports.value=[];revokeBooking.value=''}
function clear(){epoch++;list.value=[];archive.value=null;bookings.value=[];busy.value=false;ready.value=false;error.value='';feedback.value='';clearInputs();nickname.value='';grade.value='';goals.value=''}
watch(identity,clear,{flush:'sync'})
function leave(){clear()}
onHide(leave);onUnload(leave)
onLoad(o=>{requestedBooking.value=String(o?.bookingId||'');requestedSubmission.value=String(o?.submissionId||'')})
const own=computed(()=>archive.value?.access==='owner')
const activeBookings=computed(()=>archive.value?.bookings.filter(b=>b.status==='accepted')||[])
const bindingCandidates=computed(()=>bookings.value.filter(b=>!b.archiveId))
const chosenBooking=computed(()=>archive.value?.bookings.find(b=>b.id===selectedBooking.value))
const teacherCanWork=computed(()=>role.value==='tutor'&&archive.value?.access==='learning'&&chosenBooking.value?.status==='accepted'&&chosenBooking.value.teacherId===currentSession.value?.user.id)
const tabs=[{id:'overview',label:'学情总览'},{id:'learning',label:'作业与训练'},{id:'permissions',label:'试课与授权'},{id:'handover',label:'换师交接'}]
const accessLabels={owner:'家长完整档案',basic:'基础需求可见',summary:'已确认摘要可见',learning:'学习记录已授权'}
function apply(data:StudentArchiveDTO){archive.value=data;nickname.value=data.nickname;grade.value=data.grade;goals.value=data.goals;const ids=data.bookings.map(b=>b.id);if(!ids.includes(selectedBooking.value))selectedBooking.value=ids.includes(requestedBooking.value)?requestedBooking.value:ids[0]||'';if(requestedSubmission.value&&ids.includes(requestedBooking.value)){submissionId.value=requestedSubmission.value;requestedSubmission.value='';tab.value='learning'}}
async function load(){
 const v=++epoch;busy.value=true;error.value='';ready.value=false
 try{
  await restoreSession();if(v!==epoch)return
  const owner=identity();if(!allowed.value)return
  const [rows,candidates]=await Promise.all([archiveService.list(),archiveService.bookings()]);if(v!==epoch||owner!==identity())return
  list.value=rows;bookings.value=candidates
  const target=rows.find(s=>s.id===archive.value?.id)||rows.find(s=>s.bookings.some(b=>b.id===requestedBooking.value))||rows[0]
  if(target){const data=await archiveService.read(target.id);if(v===epoch&&owner===identity())apply(data)}
 }catch(e){if(v===epoch)error.value=errorMessage(e)}finally{if(v===epoch){busy.value=false;ready.value=true}}
}
onShow(async()=>{await load();if(allowed.value&&!ready.value&&!busy.value)await load()})
async function select(id:string){if(busy.value)return;const v=++epoch,owner=identity();busy.value=true;error.value='';feedback.value='';clearInputs();try{const result=await archiveService.read(id);if(v===epoch&&owner===identity())apply(result)}catch(e){if(v===epoch)error.value=errorMessage(e)}finally{if(v===epoch)busy.value=false}}
async function run(action:ArchiveAction,message:string,replay?:PendingAction){
 if(busy.value||!archive.value)return
 const v=++epoch,owner=identity(),id=archive.value.id,operation=replay||{id,revision:archive.value.revision,action:JSON.parse(JSON.stringify(action)) as ArchiveAction,requestId:archiveRequestId(),message,owner}
 if(operation.owner!==owner||operation.id!==id)return
 busy.value=true;error.value='';feedback.value='';canRetry.value=false;pendingAction=null
 try{const result=await archiveService.command(id,operation.revision,operation.action,operation.requestId);if(v!==epoch||owner!==identity())return;apply(result);list.value=list.value.map(s=>s.id===id?result:s);feedback.value=message;const candidates=await archiveService.bookings();if(v===epoch&&owner===identity())bookings.value=candidates}
 catch(e){if(v===epoch){error.value=errorMessage(e);if(e instanceof BusinessError&&e.code==='STORAGE'){pendingAction=operation;canRetry.value=true}try{const result=await archiveService.read(id);if(v===epoch&&owner===identity())apply(result)}catch{if(v===epoch)archive.value=null}}}
 finally{if(v===epoch)busy.value=false}
}
async function retry(){const p=pendingAction;if(p)await run(p.action,p.message,p)}
async function create(){
 if(busy.value)return;const v=++epoch,owner=identity();busy.value=true;error.value=''
 const fingerprint=JSON.stringify([nickname.value,grade.value,goals.value]);if(!creationKey||creationKey.fingerprint!==fingerprint)creationKey={fingerprint,requestId:archiveRequestId()}
 try{const data=await archiveService.create({nickname:nickname.value,grade:grade.value,goals:goals.value,requestId:creationKey.requestId});if(v===epoch&&owner===identity()){clearInputs();apply(data);list.value.push(data);feedback.value='学生档案已创建。请选择要关联的预约。'}}catch(e){if(v===epoch)error.value=errorMessage(e)}finally{if(v===epoch)busy.value=false}
}
function newStudent(){archive.value=null;nickname.value='';grade.value='';goals.value='';feedback.value='';clearInputs()}
function sample(){question.value='计算 1/2 + 1/3，并写出过程。';answer.value='分子与分母分别相加，得到 2/5。';reference.value='5/6';submissionId.value='';consent.value=false}
async function review(mode:'sample'|'model'){
 if(!selectedBooking.value){error.value='请先选择已关联的进行中预约';return}
 if(mode==='sample'){sample()}
 await run({type:'createReview',payload:{bookingId:selectedBooking.value,question:question.value,answer:answer.value,referenceAnswer:reference.value,submissionId:submissionId.value.trim()||undefined,consent:mode==='sample'||consent.value,mode}},mode==='sample'?'已载入固定演示分析，非本次实时模型生成；等待对应教师审核。':'模型分析已保存，等待对应教师审核。')
}
function draftReport(r:ArchiveReview){
 reportReviewId.value=r.id;reportId.value=''
 const attempts=archive.value?.attempts?.filter(a=>a.reviewId===r.id)||[]
 reportText.value=`学习依据：${r.question}\n知识点：${r.analysis.knowledgePoints.join('、')}\n作业分析：${r.analysis.analysis}\n教师建议：${r.analysis.teachingAdvice}\n训练提交：${attempts.length} 次。\n`+attempts.map(a=>`${formatTime(a.createdAt)}：`+a.answers.map(x=>`${x.questionId}=${x.answer}`).join('；')).join('\n')
 nextLesson.value=`针对 ${r.analysis.trainingTargets.join('、')} 进行复习。\n先让学生说明原题思路，再完成针对训练并讲解关键步骤。\n${r.analysis.teachingAdvice}`
}
function editReport(r:ArchiveReport){reportReviewId.value=r.reviewId;reportId.value=r.id;reportText.value=r.text;nextLesson.value=r.nextLesson}
function editReview(r:ArchiveReview){editingReview.value={id:r.id,analysis:JSON.parse(JSON.stringify(r.analysis)),teacherNote:r.teacherNote||''}}
function reviewLines(which:'knowledgePoints'|'trainingTargets',event:any){if(editingReview.value)editingReview.value.analysis[which]=String(event.detail?.value??event.target?.value??'').split('\n').filter(Boolean)}
async function saveReview(){const r=editingReview.value;if(!r)return;await run({type:'reviseReview',payload:{reviewId:r.id,analysis:r.analysis,teacherNote:r.teacherNote}},'教师修订已保存，请核对后确认分析与训练。');if(!error.value)editingReview.value=null}
async function saveObservation(){await run(observationId.value?{type:'updateObservation',payload:{observationId:observationId.value,text:observation.value}}:{type:'observe',payload:{bookingId:selectedBooking.value,text:observation.value}},'教学观察已保存。');if(!error.value){observationId.value='';observation.value=''}}
function nextClass(r:ArchiveReport){uni.navigateTo({url:`/pages/teaching/edit?bookingId=${encodeURIComponent(r.bookingId)}&archiveId=${encodeURIComponent(archive.value!.id)}&reportId=${encodeURIComponent(r.id)}`})}
async function confirmForArchive(title:string,content:string){const owner=identity(),id=archive.value?.id,booking=selectedBooking.value;try{return await confirmAction(title,content)&&owner===identity()&&id===archive.value?.id&&booking===selectedBooking.value}catch(e){if(owner===identity())error.value=errorMessage(e);return false}}
async function grant(){
 const days=Number(grantDays.value);if(!Number.isInteger(days)||days<1||days>90){error.value='授权天数请输入1—90的整数';return}
 if(!await confirmForArchive('确认档案授权',`向当前预约教师开放${grantLevel.value==='summary'?'已确认摘要':'作业、训练及已确认报告'}，有效期 ${days} 天。可随时撤销。`))return
 await run({type:'grant',payload:{bookingId:selectedBooking.value,level:grantLevel.value,expiresAt:new Date(Date.now()+days*86400000).toISOString()}},'授权已保存。')
}
async function revoke(bookingId:string){if(await confirmForArchive('撤销云档案授权','撤销后不能继续读取这份云档案的学习详情。教师已合法持有的原课次资料仍按原规则保留。'))await run({type:'revoke',payload:{bookingId}},'已撤销云档案授权。')}
function chooseReport(id:string){selectedReports.value=selectedReports.value.includes(id)?selectedReports.value.filter(x=>x!==id):[...selectedReports.value,id]}
async function handover(){if(await confirmForArchive('确认交接摘要','将选中的已确认报告保存为交接摘要。新教师需完成试课并由你授权后才可查看。'))await run({type:'handover',payload:{reportIds:selectedReports.value,revokeBookingId:revokeBooking.value||undefined}},'交接摘要已保存；请为新教师完成试课和授权。')}
const login=()=>uni.navigateTo({url:'/pages/auth/login'})
</script>
<template>
 <TeachingShell title="云伴学 · 学情档案" :role="role">
  <view class="ai-review archive-page">
   <view class="ai-intro"><text class="ai-kicker">云伴学 / 持续成长</text><text class="ai-heading">让每一次学习，都有迹可循。</text><text class="ai-description">从作业诊断到下一课备课，学习记录随学生延续，交接由家长决定。</text></view>
   <view v-if="!allowed" class="ai-glass"><text>请登录学生/家长或教师账户查看自己的学情档案。</text><button class="ai-primary" @click="login">前往登录</button></view>
   <template v-else>
    <view class="ai-state archive-toolbar"><view class="student-chips"><button v-for="s in list" :key="s.id" :class="s.id===archive?.id?'ai-primary':'ai-secondary'" :disabled="busy" @click="select(s.id)">{{s.nickname}} · {{s.grade}}</button><button v-if="role==='parent'" class="ai-secondary" :disabled="busy" @click="newStudent">＋ 新建学生</button></view><button class="ai-secondary" :disabled="busy" @click="load">刷新档案</button></view>
    <text v-if="error" class="ai-error" role="alert">{{error}}</text><button v-if="canRetry&&archive" class="ai-secondary" :disabled="busy" @click="retry">重试上次提交（同一请求）</button><text v-if="feedback" class="ai-success" role="status">{{feedback}}</text>
    <view v-if="!ready" class="ai-glass ai-empty">正在读取学情档案…</view>
    <view v-else-if="!archive" class="ai-glass">
     <template v-if="role==='parent'"><view class="ai-card-head">为学生创建独立档案</view><text class="ai-hint">同名学生也有不同档案。请使用虚构学习称呼，不填写身份证、住址或联系方式。</text><label class="ai-field"><text>学习称呼</text><input :disabled="busy" v-model="nickname" maxlength="30" aria-label="学习称呼" placeholder="例如：小禾"/></label><label class="ai-field"><text>年级</text><input :disabled="busy" v-model="grade" maxlength="30" aria-label="年级" placeholder="例如：初一"/></label><label class="ai-field"><text>学习目标</text><textarea :disabled="busy" v-model="goals" maxlength="1000" aria-label="学习目标" placeholder="希望在哪些知识点得到帮助？"/></label><view class="ai-actions"><button class="ai-primary" :disabled="busy||!nickname.trim()||!grade.trim()||!goals.trim()" data-testid="create-archive" @click="create">创建学生档案</button></view></template>
     <template v-else><view class="ai-card-head">还没有关联学生</view><text class="ai-empty">家长将预约关联至学生档案后，你可以先查看基本需求，并记录试课观察。</text></template>
    </view>
    <template v-else>
     <view class="archive-identity ai-glass"><view><text class="ai-kicker">学生档案 · {{archive.id.slice(-8)}}</text><view class="archive-name">{{archive.nickname}} <text>{{archive.grade}}</text></view><text class="ai-description">{{archive.goals}}</text></view><text class="ai-pill">{{accessLabels[archive.access]}}</text></view>
     <view class="archive-tabs"><button v-for="t in tabs" :key="t.id" :class="tab===t.id?'ai-primary':'ai-secondary'" @click="tab=t.id">{{t.label}}</button></view>
     <view class="ai-glass booking-picker"><text class="ai-hint">当前教学预约（每条分析、训练与报告均归属具体预约）</text><view class="student-chips"><button v-for="b in archive.bookings" :key="b.id" :class="selectedBooking===b.id?'ai-primary':'ai-secondary'" :disabled="busy" @click="selectedBooking=b.id;clearInputs()">{{b.teacherName}} · {{b.subject}} · {{b.status==='accepted'?'进行中':b.status==='pending'?'待确认':'已结束'}}</button><text v-if="!archive.bookings.length" class="ai-empty">尚未关联预约。请在“试课与授权”中关联。</text></view></view>
     <template v-if="tab==='overview'">
      <view class="ai-review-grid">
       <view class="ai-glass"><view class="ai-card-head">学习轨迹 <text class="ai-pill">来自已确认记录</text></view><text v-if="!archive.reports?.filter(r=>r.confirmedAt).length" class="ai-empty">还没有已确认报告。完成作业诊断与训练后，由教师审核形成备课依据。</text><view v-for="r in archive.reports?.filter(r=>r.confirmedAt)" :key="r.id" class="archive-record"><text class="ai-kicker">{{formatTime(r.confirmedAt!)}} · 教师已确认</text><text class="archive-prose">{{r.text}}</text><text class="archive-label">下一课建议</text><text class="archive-prose">{{r.nextLesson}}</text><button v-if="teacherCanWork&&r.bookingId===selectedBooking" class="ai-secondary" :disabled="busy" @click="nextClass(r)">用于下一课草稿</button></view></view>
       <view class="ai-glass"><view class="ai-card-head">教学观察</view><text class="ai-hint">记录具体表现及证据，不为学生贴性格或能力标签。</text><view v-for="o in archive.observations" :key="o.id" class="archive-record"><text class="ai-kicker">{{formatTime(o.createdAt)}}</text><text class="archive-prose">{{o.text}}</text><button v-if="teacherCanWork&&o.bookingId===selectedBooking" class="ai-secondary" @click="observationId=o.id;observation=o.text">更正这条教学观察</button></view><template v-if="teacherCanWork"><label class="ai-field"><text>本次观察与改进建议</text><textarea :disabled="busy" v-model="observation" maxlength="1500" aria-label="教学观察" placeholder="例如：今天在移项时漏掉符号，下一次先口述等式变形规则。"/></label><button class="ai-primary" :disabled="busy||!observation.trim()" @click="saveObservation">保存教学观察</button></template><text v-if="archive.access==='basic'" class="ai-empty">试课前只展示基础需求。家长确认试课并授权后，才能查看相应学习记录。</text></view>
      </view>
      <view v-if="own" class="ai-glass archive-block"><view class="ai-card-head">更正档案基础信息</view><label class="ai-field"><text>学习称呼</text><input :disabled="busy" v-model="nickname" maxlength="30" aria-label="修改学习称呼"/></label><label class="ai-field"><text>年级</text><input :disabled="busy" v-model="grade" maxlength="30" aria-label="修改年级"/></label><label class="ai-field"><text>学习目标</text><textarea :disabled="busy" v-model="goals" maxlength="1000" aria-label="修改学习目标"/></label><view class="ai-actions"><button class="ai-secondary" :disabled="busy" @click="run({type:'updateProfile',payload:{nickname,grade,goals}},'基础信息已更新。')">保存基础信息</button></view></view>
     </template>
     <template v-if="tab==='learning'">
      <view v-if="own" class="ai-glass"><view class="ai-card-head">01 · 作业诊断 <text class="ai-pill">云伴学</text></view><text class="ai-hint">文字可以来自学生确认的图片识别结果；原图片批改入口仍保留。学习分析先生成待审稿，教师确认后开展针对训练。</text><label class="ai-field"><text>题目</text><textarea :disabled="busy" v-model="question" maxlength="2500" aria-label="档案题目"/></label><label class="ai-field"><text>学生作答</text><textarea :disabled="busy" v-model="answer" maxlength="2500" aria-label="档案学生作答"/></label><label class="ai-field"><text>参考答案（选填）</text><input :disabled="busy" v-model="reference" maxlength="1000" aria-label="档案参考答案"/></label><label v-if="apiMode" class="ai-field"><text>原作业提交编号（选填）</text><input :disabled="busy" v-model="submissionId" maxlength="100" aria-label="原作业提交编号"/><text class="ai-hint">从课次作业进入时带入编号，服务端核对预约及提交归属；不自动读取附件。</text></label><checkbox-group @change="consent=($event.detail.value as string[]).includes('yes')"><label class="ai-check"><checkbox value="yes" :checked="consent"/><text>已移除个人信息，同意把这些学习文字发送给配置的模型服务。</text></label></checkbox-group><view class="ai-actions"><button class="ai-primary" :disabled="busy||!activeBookings.some(b=>b.id===selectedBooking)||!question.trim()||!answer.trim()||!consent||!archive.modelEnabled" @click="review('model')">生成分析与针对训练</button><button class="ai-secondary" :disabled="busy||!activeBookings.some(b=>b.id===selectedBooking)" data-testid="sample-review" @click="review('sample')">体验固定示例（非实时生成）</button></view><text v-if="!archive.modelEnabled" class="ai-hint">{{apiMode?'管理员尚未启用模型，仍可体验固定示例流程。':'本机模式不调用模型。固定示例仅用于功能演示。'}}</text></view>
      <view v-for="r in archive.reviews" :key="r.id" class="ai-glass archive-block" data-testid="archive-review"><view class="ai-card-head">{{r.confirmedAt?'02 · 已确认训练':'01 · 待教师审核'}} <text class="ai-pill">{{r.source==='model'?'模型生成 · 教师复核':'固定示例 · 非实时生成'}}</text></view><text class="ai-kicker">{{formatTime(r.createdAt)}} · {{r.id.slice(-8)}}</text><text class="archive-label">原题 / 作答</text><text class="archive-prose">{{r.question+'\n'+r.answer}}</text><text class="archive-label">{{r.analysis.knowledgePoints.join(' · ')}}</text><text class="archive-prose">{{r.analysis.analysis}}</text><text class="archive-prose">{{r.analysis.teachingAdvice}}</text><text v-if="r.teacherNote" class="archive-prose">教师补充：{{r.teacherNote}}</text><view v-for="q in r.analysis.questions" :key="q.id" class="archive-question"><text class="archive-label">{{q.id}} · {{q.stem}}</text><label v-if="own&&r.confirmedAt" class="ai-field"><text>你的训练作答</text><textarea :disabled="busy" v-model="answers[r.id+':'+q.id]" maxlength="2000" :aria-label="'训练作答'+q.id"/></label><text v-if="role==='tutor'" class="archive-prose">{{'参考答案：'+q.answer+'\n'+q.explanation}}</text></view><view v-for="a in archive.attempts?.filter(a=>a.reviewId===r.id)" :key="a.id" class="archive-record"><text class="ai-kicker">训练提交 · {{formatTime(a.createdAt)}}</text><text v-for="x in a.answers" :key="x.questionId" class="archive-prose">{{x.questionId}}：{{x.answer}}</text></view><view v-if="editingReview?.id===r.id" class="review-editor"><view class="archive-label">教师修订 · 确认前可以更正分析和训练</view><label class="ai-field"><text>知识点（每项一行）</text><textarea :disabled="busy" :value="editingReview.analysis.knowledgePoints.join('\n')" maxlength="1000" @input="reviewLines('knowledgePoints',$event)"/></label><label class="ai-field"><text>错因分析</text><textarea :disabled="busy" v-model="editingReview.analysis.analysis" maxlength="1500"/></label><label class="ai-field"><text>教学建议</text><textarea :disabled="busy" v-model="editingReview.analysis.teachingAdvice" maxlength="1500"/></label><label class="ai-field"><text>训练目标（每项一行）</text><textarea :disabled="busy" :value="editingReview.analysis.trainingTargets.join('\n')" maxlength="1500" @input="reviewLines('trainingTargets',$event)"/></label><view v-for="q in editingReview.analysis.questions" :key="q.id" class="archive-question"><label class="ai-field"><text>{{q.id}} · 训练题目</text><textarea :disabled="busy" v-model="q.stem" maxlength="1500"/></label><label class="ai-field"><text>参考答案</text><textarea :disabled="busy" v-model="q.answer" maxlength="1500"/></label><label class="ai-field"><text>讲解</text><textarea :disabled="busy" v-model="q.explanation" maxlength="1500"/></label></view><label class="ai-field"><text>教师补充说明</text><textarea :disabled="busy" v-model="editingReview.teacherNote" maxlength="2000"/></label><view class="ai-actions"><button class="ai-primary" :disabled="busy" @click="saveReview">保存教师修订</button><button class="ai-secondary" :disabled="busy" @click="editingReview=null">放弃未保存修订</button></view></view><view class="ai-actions"><button v-if="teacherCanWork&&r.bookingId===selectedBooking&&!r.confirmedAt" class="ai-secondary" :disabled="busy" @click="editReview(r)">修订分析与训练</button><button v-if="teacherCanWork&&r.bookingId===selectedBooking&&!r.confirmedAt" class="ai-primary" :disabled="busy" data-testid="confirm-review" @click="run({type:'confirmReview',payload:{reviewId:r.id,teacherNote:r.teacherNote||'已核对原题、分析和训练参考答案。'}},'分析与训练已由教师确认。')">核对后确认分析与训练</button><button v-if="own&&r.confirmedAt" class="ai-primary" :disabled="busy" data-testid="submit-training" @click="run({type:'submitAttempt',payload:{reviewId:r.id,answers:r.analysis.questions.map(q=>({questionId:q.id,answer:answers[r.id+':'+q.id]||''}))}},'训练作答已提交，等待教师分析。')">提交本轮训练</button><button v-if="teacherCanWork&&r.bookingId===selectedBooking&&r.confirmedAt" class="ai-secondary" @click="draftReport(r)">整理备课报告草稿</button></view></view>
      <view v-if="reportReviewId&&teacherCanWork" class="ai-glass archive-block"><view class="ai-card-head">03 · 核对备课报告</view><text class="ai-hint">草稿根据原分析与实际训练提交整理。请结合学生的具体作答修改，不将示例当作真实学情。</text><label class="ai-field"><text>学情报告正文</text><textarea :disabled="busy" v-model="reportText" maxlength="5000" aria-label="学情报告正文" class="report-text"/></label><label class="ai-field"><text>下一课备课建议</text><textarea :disabled="busy" v-model="nextLesson" maxlength="3000" aria-label="下一课备课建议"/></label><view class="ai-actions"><button class="ai-primary" :disabled="busy" @click="run({type:'saveReport',payload:{reviewId:reportReviewId,reportId:reportId||undefined,text:reportText,nextLesson}},'备课报告草稿已保存，核对后请确认。')">保存备课报告草稿</button></view></view>
      <view v-for="r in archive.reports" :key="r.id" class="ai-glass archive-block"><view class="ai-card-head">{{r.confirmedAt?'教师已确认报告':'待确认备课报告'}}</view><text class="archive-prose">{{r.text}}</text><text class="archive-label">下一课建议</text><text class="archive-prose">{{r.nextLesson}}</text><view v-if="teacherCanWork&&r.bookingId===selectedBooking" class="ai-actions"><button v-if="!r.confirmedAt" class="ai-secondary" @click="editReport(r)">编辑报告</button><button v-if="!r.confirmedAt" class="ai-primary" :disabled="busy" data-testid="confirm-report" @click="run({type:'confirmReport',payload:{reportId:r.id}},'报告已确认，可用于下一课和家长交接。')">确认备课报告</button><button v-else class="ai-secondary" @click="nextClass(r)">用于下一课草稿</button></view></view>
      <view v-if="!archive.reviews" class="ai-glass ai-empty">当前权限尚未开放作业与训练详情，请查看“试课与授权”。</view>
     </template>
     <template v-if="tab==='permissions'">
      <view class="ai-review-grid"><view class="ai-glass"><view class="ai-card-head">关联预约与试课</view><text class="ai-hint">关联预约不会自动开放全部历史。教师先记录试课，家长确认后再决定授权。</text><template v-if="own"><view v-for="b in bindingCandidates" :key="b.id" class="archive-record"><text>{{b.teacherName}} · {{b.subject}} · {{b.id.slice(-8)}}</text><button class="ai-secondary" :disabled="busy" data-testid="bind-booking" @click="run({type:'bindBooking',payload:{bookingId:b.id}},'预约已关联，等待教师记录试课。')">关联这个预约</button></view></template><template v-if="role==='tutor'&&chosenBooking?.status==='accepted'"><label class="ai-field"><text>试课观察（可核对的具体事实）</text><textarea :disabled="busy" v-model="trial" maxlength="1500" aria-label="试课观察"/></label><button class="ai-primary" :disabled="busy||!trial.trim()" data-testid="record-trial" @click="run({type:'recordTrial',payload:{bookingId:selectedBooking,observation:trial}},'试课观察已提交，等待家长确认。')">提交试课记录</button></template><view v-for="t in archive.trials" :key="t.id" class="archive-record"><text class="archive-prose">{{t.observation}}</text><text class="ai-kicker">{{formatTime(t.createdAt)}} · {{t.confirmedAt?'家长已确认':'等待家长确认'}}</text><button v-if="own&&!t.confirmedAt" class="ai-primary" :disabled="busy" data-testid="confirm-trial" @click="run({type:'confirmTrial',payload:{trialId:t.id}},'试课已确认；是否开放学情仍由你决定。')">确认已完成这次试课</button></view></view>
       <view class="ai-glass"><view class="ai-card-head">分级授权</view><text class="ai-hint">基础需求始终对关联教师可见。摘要只含已确认学习报告；详细权限包含作业与训练。教师已持有的原课次资料遵循原有规则。</text><template v-if="own"><view class="ai-actions"><button :class="grantLevel==='summary'?'ai-primary':'ai-secondary'" @click="grantLevel='summary'">已确认摘要</button><button :class="grantLevel==='learning'?'ai-primary':'ai-secondary'" @click="grantLevel='learning'">作业与训练详情</button></view><label class="ai-field"><text>授权天数（1—90天）</text><input :disabled="busy" v-model="grantDays" type="number" aria-label="授权天数"/></label><view class="ai-actions"><button class="ai-primary" :disabled="busy||!selectedBooking" data-testid="grant-access" @click="grant">确认授权当前预约教师</button></view><view v-for="g in archive.grants" :key="g.bookingId" class="archive-record"><text>{{archive.bookings.find(b=>b.id===g.bookingId)?.teacherName||'关联教师'}} · {{g.level==='summary'?'摘要':'学习详情'}}</text><text class="ai-hint">{{g.revokedAt?'已撤销':new Date(g.expiresAt).getTime()<=Date.now()?'已到期':'有效至 '+formatTime(g.expiresAt)}}</text><button v-if="!g.revokedAt" class="ai-secondary" :disabled="busy" @click="revoke(g.bookingId)">撤销该教师授权</button></view></template><text v-else class="ai-empty">当前：{{accessLabels[archive.access]}}。授权范围与期限由家长管理。</text></view></view>
     </template>
     <template v-if="tab==='handover'">
      <view class="ai-glass"><view class="ai-card-head">学习不断档，交接有依据。</view><text class="ai-hint">只把家长选定的已确认报告纳入交接。新教师完成自己的试课并获得家长授权后，才能读取对应内容。</text><template v-if="own"><view v-for="r in archive.reports?.filter(r=>r.confirmedAt)" :key="r.id" class="archive-record"><button :class="selectedReports.includes(r.id)?'ai-primary':'ai-secondary'" @click="chooseReport(r.id)">{{selectedReports.includes(r.id)?'已选择':'选择报告'}} · {{formatTime(r.confirmedAt!)}}</button><text class="archive-prose">{{r.text}}</text></view><label class="ai-field"><text>同时撤销旧教师授权（选填）</text><picker :range="['不同时撤销',...archive.bookings.map(b=>b.teacherName+' · '+b.subject)]" @change="revokeBooking=Number($event.detail.value)>0?archive.bookings[Number($event.detail.value)-1]!.id:''"><view class="archive-select">{{archive.bookings.find(b=>b.id===revokeBooking)?.teacherName||'不同时撤销'}}</view></picker></label><view class="ai-actions"><button class="ai-primary" :disabled="busy||!selectedReports.length" @click="handover">保存家长确认的交接摘要</button></view><text v-if="!archive.reports?.some(r=>r.confirmedAt)" class="ai-empty">还没有可交接的已确认报告。</text></template><view v-for="h in archive.handovers" :key="h.id" class="archive-record"><text class="ai-kicker">家长确认的交接快照 · {{formatTime(h.createdAt)}}</text><view v-for="s in h.snapshots" :key="s.reportId"><text class="ai-hint">来源报告 {{s.reportId.slice(-8)}} · {{formatTime(s.confirmedAt)}}</text><text class="archive-prose">{{s.text}}</text><text class="archive-prose">{{s.nextLesson}}</text></view></view></view>
     </template>
    </template>
   </template>
  </view>
 </TeachingShell>
</template>
