<style scoped>
.archive-page{padding-bottom:60px;overflow-wrap:anywhere}.archive-toolbar{display:flex;justify-content:space-between;align-items:center;gap:14px}.student-chips,.archive-tabs{display:flex;flex-wrap:wrap;gap:10px}.archive-tabs{margin:22px 0}.student-chips{margin:12px 0}.archive-identity{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-top:22px}.archive-name{font-family:'Songti SC',serif;font-size:32px;font-weight:700;margin:8px 0}.archive-name text{font-family:inherit;font-size:16px;color:var(--ai-muted);margin-left:12px}.booking-picker{margin-bottom:22px}.archive-block{margin-top:22px}.archive-record{border-top:1px solid var(--ai-border);padding-top:18px;margin-top:20px}.archive-label{display:block;font-size:15px;font-weight:600;margin:16px 0 8px}.archive-prose{display:block;white-space:pre-wrap;line-height:1.85;margin:8px 0 16px}.archive-question{background:#f3f5ed99;border-radius:12px;padding:4px 16px 14px;margin-top:16px}.archive-select{border:1px solid var(--ai-border);padding:12px;border-radius:12px;background:var(--ai-paper)}.report-text{height:300px!important}@media(max-width:760px){.archive-toolbar,.archive-identity{align-items:flex-start;flex-direction:column}.archive-name{font-size:27px}.archive-tabs{display:grid;grid-template-columns:1fr 1fr}.archive-tabs button{width:100%;box-sizing:border-box}.student-chips button{max-width:100%;overflow-wrap:anywhere}.archive-identity .ai-pill{white-space:normal}}
</style>
